// Extraer datos del formulario
const formData = $input.first().json;

// Construir objeto con los datos del formulario
const nombre = formData['Nombre'] || '';
const cedula = formData['Cedula'] || '';

// Extraer archivos (vienen como binary data)
const binary = $input.first().binary || {};

// Los campos file del formulario vienen como binarios
const tituloFile = binary['Titulo'] ? binary['Titulo'] : null;
const creditosFile = binary['Creditos'] ? binary['Creditos'] : null;
const copiaFile = binary['Copia de Cedula'] ? binary['Copia de Cedula'] : null;

// Convertir imágenes a base64 para incrustar en HTML
function getBase64Image(binaryData) {
  if (!binaryData) return null;
  const mimeType = binaryData.mimeType || 'image/jpeg';
  const data = binaryData.data || '';
  return `data:${mimeType};base64,${data}`;
}

const tituloBase64 = getBase64Image(tituloFile);
const creditosBase64 = getBase64Image(creditosFile);
const copiaBase64 = getBase64Image(copiaFile);

// Generar fecha actual
const fechaActual = new Date().toLocaleDateString('es-CO', {
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

// Generar HTML para el PDF
const html = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: Arial, sans-serif;
      font-size: 12px;
      color: #333;
      padding: 30px;
    }
    .header {
      text-align: center;
      border-bottom: 3px solid #2c3e50;
      padding-bottom: 20px;
      margin-bottom: 30px;
    }
    .header h1 {
      font-size: 24px;
      color: #2c3e50;
      margin-bottom: 5px;
    }
    .header p {
      color: #7f8c8d;
      font-size: 11px;
    }
    .section {
      margin-bottom: 25px;
      padding: 15px;
      border: 1px solid #ddd;
      border-radius: 5px;
      background: #f9f9f9;
    }
    .section h2 {
      font-size: 14px;
      color: #2c3e50;
      margin-bottom: 12px;
      padding-bottom: 5px;
      border-bottom: 1px solid #ddd;
    }
    .field-row {
      display: flex;
      margin-bottom: 8px;
    }
    .field-label {
      font-weight: bold;
      width: 150px;
      color: #555;
    }
    .field-value {
      color: #333;
    }
    .image-section {
      margin-bottom: 25px;
    }
    .image-section h2 {
      font-size: 14px;
      color: #2c3e50;
      margin-bottom: 10px;
      padding: 8px 15px;
      background: #2c3e50;
      color: white;
      border-radius: 4px;
    }
    .image-container {
      text-align: center;
      padding: 10px;
      border: 1px solid #ddd;
      border-radius: 5px;
      background: white;
    }
    .image-container img {
      max-width: 100%;
      max-height: 400px;
      object-fit: contain;
      border: 1px solid #eee;
    }
    .no-image {
      padding: 20px;
      color: #999;
      font-style: italic;
      text-align: center;
    }
    .footer {
      margin-top: 30px;
      text-align: center;
      font-size: 10px;
      color: #999;
      border-top: 1px solid #ddd;
      padding-top: 15px;
    }
  </style>
</head>
<body>
  <div class="header">
    <h1>Registro de Datos</h1>
    <p>Generado el ${fechaActual}</p>
  </div>

  <div class="section">
    <h2>Información Personal</h2>
    <div class="field-row">
      <span class="field-label">Nombre:</span>
      <span class="field-value">${nombre}</span>
    </div>
    <div class="field-row">
      <span class="field-label">Cédula:</span>
      <span class="field-value">${cedula}</span>
    </div>
  </div>

  <div class="image-section">
    <h2>Título</h2>
    <div class="image-container">
      ${tituloBase64
        ? `<img src="${tituloBase64}" alt="Título" />`
        : '<p class="no-image">Imagen no disponible</p>'
      }
    </div>
  </div>

  <div class="image-section">
    <h2>Créditos</h2>
    <div class="image-container">
      ${creditosBase64
        ? `<img src="${creditosBase64}" alt="Créditos" />`
        : '<p class="no-image">Imagen no disponible</p>'
      }
    </div>
  </div>

  <div class="image-section">
    <h2>Copia de Cédula</h2>
    <div class="image-container">
      ${copiaBase64
        ? `<img src="${copiaBase64}" alt="Copia de Cédula" />`
        : '<p class="no-image">Imagen no disponible</p>'
      }
    </div>
  </div>

  <div class="footer">
    <p>Documento generado automáticamente — Cédula: ${cedula}</p>
  </div>
</body>
</html>
`;

return [{
  json: {
    nombre,
    cedula,
    fechaGeneracion: fechaActual,
    htmlContent: html
  },
  binary
}];

// Opción B: Generar PDF usando librería puppeteer (si está disponible en el entorno)
// Este nodo es una alternativa si no se usa API externa

const htmlContent = $input.first().json.htmlContent;
const nombre = $input.first().json.nombre;
const cedula = $input.first().json.cedula;

// Si n8n tiene acceso a puppeteer vía custom node o ejecuta scripts externos:
// En entornos n8n self-hosted se puede usar el nodo 'Execute Command' con:
// node generate_pdf.js

// Para este nodo Code, simplemente pasamos el HTML listo
return [{
  json: {
    nombre,
    cedula,
    htmlContent,
    fileName: `registro_${cedula}_${Date.now()}.pdf`
  },
  binary: $input.first().binary
}];
